function [u,balancing] = furuta_lqr_bal_step(x,active)
%#codegen
% Generated by lm_export_step: observer + (NO swing-up, balance only) + LQR (comparison-baseline plant).
persistent xh c1 c2 bal home iint
x=double(x(:)); u=0; balancing=false;
if isempty(xh) || ~active
    xh=[x(1);x(2);0;0]; c1=0; c2=0; bal=false; home=0; iint=0;
    if ~active, u=0; balancing=false; return; end
else
    xp=lmRk4(xh,c2);
    e=[atan2(sin(x(1)-xp(1)),cos(x(1)-xp(1))); atan2(sin(x(2)-xp(2)),cos(x(2)-xp(2)))];
    xh=xp+[0.99874041873644015 -3.4004607738870156e-09;-2.6267750042421629e-07 0.97854123042516894;99.616807711359598 -0.00088795035447582389;0.0010374451195385593 94.042246792646438]*e;
end
xf=lmRk4(xh,c1);
th=atan2(sin(xf(2)),cos(xf(2))); w=xf(4); v=xf(3);
cap=abs(th)<0.17453292519943295 && abs(w)<2;
if cap && ~bal, home=xf(1); end
bal=(bal && abs(th)<0.69813170079773179) || cap;
if ~bal
    iint=0;
    u=0;
else
    z=[max(-0.59999999999999998,min(0.59999999999999998,xf(1)-home)); th; v; w];
    ub=[1.9068476065796245 25.027600541173026 1.039831385757038 2.5019927223768135]*z;
    if abs(v)>13.5 && sign(ub)==sign(v), ub=0; end
    u=ub+0*tanh(v/0.050000000000000003);
end
u=max(-1,min(1,u));
u=round(u*150)/150;
u=u(1); c2=c1; c1=u; balancing=logical(bal);
end

function x=lmRk4(x,a)
tau=3.1500000000000004*a; h=0.002;
for i=1:5
    k1=f(x); k2=f(x+h/2*k1); k3=f(x+h/2*k2); k4=f(x+h*k3);
    x=x+h/6*(k1+2*k2+2*k3+k4);
end
    function y=f(z)
        s=sin(z(2)); c=cos(z(2)); vv=z(3); ww=z(4);
        dd=0.050000000000000003+0.00016077999999999999*s^2; b=0.00013804999999999999*c;
        ff=tau-2*0.00016077999999999999*s*c*vv*ww+0.00013804999999999999*s*ww^2-0.0001*vv-0.63*sign(vv);
        gg=0.00016077999999999999*s*c*vv^2-1.0000000000000001e-05*ww+0.016934000000000001*s;
        dt=dd*0.00016134-b^2;
        y=[z(3);z(4);(0.00016134*ff-b*gg)/dt;(dd*gg-b*ff)/dt];
    end
end
